"""Measure generated byte-vector materialization from an unchanged native producer."""

from __future__ import annotations

import argparse
import gc
import hashlib
import json
import os
import platform
import statistics
import sys
import time
import tracemalloc
from pathlib import Path

import byte_payload
import byte_schema_support

import holoscan as hs

MODES = ("receive_data", "receive", "selected_data", "selected_metadata")


def run_case(mode, size, iterations, warmup, *, memory=False):
    """Time one receive API call; validate bytes and native control values outside timing."""
    expected = bytes(range(256)) * (size // 256) + bytes(range(size % 256))
    digest = hashlib.sha256(expected).hexdigest()
    samples = []
    consumed = 0
    total = iterations + warmup
    byte_schema_support.configure(size)

    class Consumer(hs.Operator):
        inp = hs.Input("in", byte_payload.BytePayload)

        def contract(self):
            return hs.Contract().trigger(hs.OnEach(self.inp))

        def compute(self, context):
            nonlocal consumed
            selected = self.inp.selected_sample() if mode.startswith("selected_") else None
            if memory and consumed >= warmup:
                before, _ = tracemalloc.get_traced_memory()
                tracemalloc.reset_peak()
            start = time.perf_counter_ns()
            if mode == "receive_data":
                value = self.inp.receive_data()
            elif mode == "receive":
                value = self.inp.receive()
            elif mode == "selected_data":
                value = selected.data
            else:
                value = selected.metadata
            duration = time.perf_counter_ns() - start
            if consumed >= warmup:
                if memory:
                    _, peak = tracemalloc.get_traced_memory()
                    samples.append(max(0, peak - before))
                else:
                    samples.append(duration)
            if mode == "selected_metadata":
                value = selected.data
            elif mode == "receive":
                value = value.data
            assert bytes(value.blob) == expected
            assert value.numbers == [1, 128, 65536]
            consumed += 1
            if consumed == total:
                context.request_completion()

    graph = hs.Graph("byte-vector-materialization", default_clock=hs.RealtimeClock)
    source = graph.op("holoscan.test.ByteSource", "source")
    sink = graph.op(Consumer, "sink")
    graph.add_flow(source["out"], sink["in"], queue_depth=1)
    graph.partition("serial").add(source).add(sink)
    plan = hs.compile(graph)
    gc.collect()
    if memory:
        tracemalloc.start()
    session = hs.run_async(plan)
    if not session.wait(timeout=120.0):
        session.request_stop()
        session.wait(timeout=5.0)
        raise RuntimeError("byte-vector benchmark timed out")
    if session.diagnostics:
        raise RuntimeError(str(session.diagnostics))
    assert session.termination is hs.RunTermination.REQUESTED_COMPLETED
    assert consumed == total
    assert len(samples) == iterations
    if memory:
        tracemalloc.stop()
    return {
        "mode": mode,
        "size": size,
        "digest": digest,
        "samples_python_peak_bytes" if memory else "samples_ns": samples,
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--sizes", nargs="+", type=int, default=[0, 256, 4096, 407000, 416768])
    parser.add_argument("--modes", nargs="+", choices=MODES, default=list(MODES))
    parser.add_argument("--iterations", type=int, default=100)
    parser.add_argument("--warmup", type=int, default=20)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument(
        "--memory",
        action="store_true",
        help="separate tracemalloc pass; reports Python peak bytes, not latency",
    )
    args = parser.parse_args()
    if args.iterations < 2 or args.warmup < 0 or any(size < 0 for size in args.sizes):
        parser.error("require at least two iterations, nonnegative warmup and sizes")
    results = []
    for size in args.sizes:
        for mode in args.modes:
            row = run_case(mode, size, args.iterations, args.warmup, memory=args.memory)
            if args.memory:
                results.append(row)
                print(mode, size, statistics.median(row["samples_python_peak_bytes"]), flush=True)
                continue
            ordered = sorted(row["samples_ns"])
            row.update(
                median_ns=statistics.median(ordered),
                mean_ns=statistics.mean(ordered),
                p95_ns=ordered[int(0.95 * (len(ordered) - 1))],
                p99_ns=ordered[int(0.99 * (len(ordered) - 1))],
            )
            results.append(row)
            print(mode, size, row["median_ns"], flush=True)
    args.output.write_text(
        json.dumps(
            {
                "warmup": args.warmup,
                "iterations": args.iterations,
                "memory": args.memory,
                "environment": {
                    "python": sys.version,
                    "platform": platform.platform(),
                    "affinity": sorted(os.sched_getaffinity(0)),
                    "holoscan": hs.__file__,
                    "schema": byte_payload.__file__,
                    "native_source": byte_schema_support.__file__,
                    "harness_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
                },
                "results": results,
            },
            indent=2,
        )
        + "\n"
    )


if __name__ == "__main__":
    main()
